import { useEffect, useMemo, useRef, useState } from 'react';

import { useLastDataRefresh } from 'contexts';
import { useGetExportGroupQuery } from 'redux/api/bff';

import { EXPORT_CATEGORY_GROUPS } from '../../constants';
import { buildGlobalDataForPeriod, mergeGroupCategories } from './utils';

export { buildGlobalDataForPeriod } from './utils';

function isQueryDone(query: { data?: unknown; error?: unknown }) {
  return !!query.data || !!query.error;
}

export const usePowerBookGlobalData = (
  skipYtd = false,
  filtersReady = true,
) => {
  const { lastDataRefreshKpisDateMonthYear } = useLastDataRefresh();
  const dt_end = lastDataRefreshKpisDateMonthYear?.power ?? '';

  const skipAll = !dt_end || !filtersReady;

  // QTD groups — sequential: each group waits for the previous one to finish
  const qtdGroup1 = useGetExportGroupQuery(
    { categories: [...EXPORT_CATEGORY_GROUPS[0]], dt_end, period: 'QTD' },
    { skip: skipAll },
  );
  const qtdGroup2 = useGetExportGroupQuery(
    { categories: [...EXPORT_CATEGORY_GROUPS[1]], dt_end, period: 'QTD' },
    { skip: skipAll || !isQueryDone(qtdGroup1) },
  );
  const qtdGroup3 = useGetExportGroupQuery(
    { categories: [...EXPORT_CATEGORY_GROUPS[2]], dt_end, period: 'QTD' },
    { skip: skipAll || !isQueryDone(qtdGroup2) },
  );
  const qtdGroup4 = useGetExportGroupQuery(
    { categories: [...EXPORT_CATEGORY_GROUPS[3]], dt_end, period: 'QTD' },
    { skip: skipAll || !isQueryDone(qtdGroup3) },
  );
  const qtdGroup5 = useGetExportGroupQuery(
    { categories: [...EXPORT_CATEGORY_GROUPS[4]], dt_end, period: 'QTD' },
    { skip: skipAll || !isQueryDone(qtdGroup4) },
  );

  const qtdGroups = [qtdGroup1, qtdGroup2, qtdGroup3, qtdGroup4, qtdGroup5];
  const qtdDone = qtdGroups.every(isQueryDone);

  const skipYtdAll = skipAll || !qtdDone || skipYtd;

  // YTD groups — sequential, starts after all QTD complete
  const ytdGroup1 = useGetExportGroupQuery(
    { categories: [...EXPORT_CATEGORY_GROUPS[0]], dt_end, period: 'YTD' },
    { skip: skipYtdAll },
  );
  const ytdGroup2 = useGetExportGroupQuery(
    { categories: [...EXPORT_CATEGORY_GROUPS[1]], dt_end, period: 'YTD' },
    { skip: skipYtdAll || !isQueryDone(ytdGroup1) },
  );
  const ytdGroup3 = useGetExportGroupQuery(
    { categories: [...EXPORT_CATEGORY_GROUPS[2]], dt_end, period: 'YTD' },
    { skip: skipYtdAll || !isQueryDone(ytdGroup2) },
  );
  const ytdGroup4 = useGetExportGroupQuery(
    { categories: [...EXPORT_CATEGORY_GROUPS[3]], dt_end, period: 'YTD' },
    { skip: skipYtdAll || !isQueryDone(ytdGroup3) },
  );
  const ytdGroup5 = useGetExportGroupQuery(
    { categories: [...EXPORT_CATEGORY_GROUPS[4]], dt_end, period: 'YTD' },
    { skip: skipYtdAll || !isQueryDone(ytdGroup4) },
  );

  const ytdGroups = [ytdGroup1, ytdGroup2, ytdGroup3, ytdGroup4, ytdGroup5];

  const qtdCategories = useMemo(
    () => mergeGroupCategories(qtdGroups.map((g) => g.data)),
    [
      qtdGroup1.data,
      qtdGroup2.data,
      qtdGroup3.data,
      qtdGroup4.data,
      qtdGroup5.data,
    ],
  );

  const ytdCategories = useMemo(
    () => mergeGroupCategories(ytdGroups.map((g) => g.data)),
    [
      ytdGroup1.data,
      ytdGroup2.data,
      ytdGroup3.data,
      ytdGroup4.data,
      ytdGroup5.data,
    ],
  );

  const qtdData = useMemo(
    () => buildGlobalDataForPeriod(qtdCategories),
    [qtdCategories],
  );

  const ytdData = useMemo(
    () => buildGlobalDataForPeriod(ytdCategories),
    [ytdCategories],
  );

  const allGroups = [...qtdGroups, ...ytdGroups];

  const loading = skipAll || allGroups.some((g) => !isQueryDone(g));

  const error = allGroups.some((g) => g.error)
    ? new Error('Failed to load export data')
    : null;

  const startTimeRef = useRef<number>(performance.now());
  const totalEndRef = useRef<number | null>(null);
  const [loadDurationMs, setLoadDurationMs] = useState<number | null>(null);

  useEffect(() => {
    if (!loading && totalEndRef.current === null) {
      totalEndRef.current = performance.now();
      setLoadDurationMs(totalEndRef.current - startTimeRef.current);
    }
  }, [loading]);

  return {
    qtdData,
    ytdData,
    qtdDone,
    loading,
    error,
    loadDurationMs,
  };
};
